52	impl PrLinkAccumulator {
53	    fn record(&mut self, turn_index: usize, owner: &str, repo: &str, digits: &str) {
54	        self.pr_urls.insert(CompactString::new(format!("{owner}/{repo}#{digits}")));
55	        if self.first_pr_turn_index.is_none() {
56	            self.first_pr_turn_index = Some(turn_index);
57	        }
58	    }
59	}
60	
61	impl EntryAccumulator for PrLinkAccumulator {
62	    type Output = PrLinkMetrics;
63	
64	    fn update(&mut self, entry: &CanonicalTurn) {
65	        if !entry.tool_results.is_empty() {
66	            let call_intents: BTreeMap<&CompactString, &ToolIntent> =
67	                entry.tool_calls.iter().map(|call| (&call.call_id, &call.intent)).collect();
68	
69	            for result in &entry.tool_results {
70	                let Some(output) = &result.truncated_output else { continue };
71	                let is_vcs = matches!(call_intents.get(&result.call_id), Some(ToolIntent::VersionControl { .. }));
72	
73	                for (owner, repo, digits) in find_pr_matches(output) {
74	                    self.record(entry.turn_index, &owner, &repo, &digits);
75	                    if is_vcs {
76	                        self.linked_via_vcs_tool += 1;
77	                    }
78	                }
79	            }
80	        }
81	
82	        if let Some(text) = &entry.text {
83	            for (owner, repo, digits) in find_pr_matches(text) {
84	                self.record(entry.turn_index, &owner, &repo, &digits);
85	            }
86	        }
87	    }
88	
89	    fn finalize(self) -> Self::Output {
90	        PrLinkMetrics {
91	            pr_urls: self.pr_urls,
92	            first_pr_turn_index: self.first_pr_turn_index,
93	            linked_via_vcs_tool: self.linked_via_vcs_tool,
94	        }
95	    }
96	}
