362	fn parse_tool_intent(name: &str, input: &serde_json::Value) -> ToolIntent {
363	    match name {
364	        "view_file" | "Read" | "read_file" => {
365	            let path =
366	                input.get("AbsolutePath").or_else(|| input.get("file_path")).and_then(|v| v.as_str()).unwrap_or("");
367	            ToolIntent::FileRead { path: CompactString::new(path), line_range: None }
368	        }
369	        "replace_file_content" | "Edit" | "edit_file" => {
370	            let path =
371	                input.get("TargetFile").or_else(|| input.get("file_path")).and_then(|v| v.as_str()).unwrap_or("");
372	            ToolIntent::FileEdit { path: CompactString::new(path), lines_added: 0, lines_removed: 0 }
373	        }
374	        "write_to_file" | "Write" => {
375	            let path =
376	                input.get("TargetFile").or_else(|| input.get("file_path")).and_then(|v| v.as_str()).unwrap_or("");
377	            ToolIntent::FileCreate { path: CompactString::new(path) }
378	        }
379	        "grep_search" | "rg" => {
380	            let q = input.get("Query").or_else(|| input.get("pattern")).and_then(|v| v.as_str()).unwrap_or("");
381	            ToolIntent::CodeSearch { tool: CompactString::new(name), query: CompactString::new(q), is_ast: false }
382	        }
383	        "find_by_name" | "fd" => {
384	            let p = input.get("Pattern").and_then(|v| v.as_str()).unwrap_or("");
385	            ToolIntent::FileDiscovery { tool: CompactString::new(name), pattern: CompactString::new(p) }
386	        }
387	        "run_command" | "Bash" | "bash" => {
388	            let cmd = input.get("CommandLine").or_else(|| input.get("command")).and_then(|v| v.as_str()).unwrap_or("");
389	            if cmd.starts_with("git") {
390	                ToolIntent::VersionControl { action: CompactString::new(cmd) }
391	            } else if cmd.contains("test") {
392	                ToolIntent::TestExecution { runner: CompactString::new("shell"), target_suite: None }
393	            } else {
394	                ToolIntent::Other { raw_name: CompactString::new(name) }
395	            }
396	        }
397	        _ => ToolIntent::Other { raw_name: CompactString::new(name) },
398	    }
399	}
