48	impl TokenEconomics {
49	    /// Computes full economic summary from one [`TurnPricingInput`] per turn. Each turn is
50	    /// priced independently via `pricing.rate_for` at that turn's own timestamp/tier, and the
51	    /// per-turn costs are summed into `total_cost_usd` -- required so a session whose turns
52	    /// straddle a price-change boundary is priced correctly on both sides. Token counters
53	    /// remain simple sums across turns, unaffected by the per-turn pricing. An empty `turns`
54	    /// slice returns a zeroed `TokenEconomics`, not an error.
55	    pub fn calculate(
56	        turns: &[TurnPricingInput],
57	        model_name: &str,
58	        pricing: &PricingTable,
59	        provided_cost_usd: Option<f64>,
60	    ) -> Self {
61	        let mut input_tokens = 0u64;
62	        let mut output_tokens = 0u64;
63	        let mut cache_creation_tokens = 0u64;
64	        let mut cache_read_tokens = 0u64;
65	        let mut total_cost_usd = 0.0f64;
66	        let mut baseline_cost_no_cache_usd = 0.0f64;
67	
68	        for turn in turns {
69	            let usage = &turn.usage;
70	            let tier = turn.tier.as_deref();
71	
72	            let input_rate = pricing.rate_for(model_name, tier, TokenRateKind::Input, turn.timestamp);
73	            let cache_write_rate = pricing.rate_for(model_name, tier, TokenRateKind::CacheWrite, turn.timestamp);
74	            let cache_read_rate = pricing.rate_for(model_name, tier, TokenRateKind::CacheRead, turn.timestamp);
75	            let output_rate = pricing.rate_for(model_name, tier, TokenRateKind::Output, turn.timestamp);
76	
77	            let turn_cost = (usage.input_tokens as f64 / 1_000_000.0) * input_rate
78	                + (usage.cache_creation_tokens as f64 / 1_000_000.0) * cache_write_rate
79	                + (usage.cache_read_tokens as f64 / 1_000_000.0) * cache_read_rate
80	                + (usage.output_tokens as f64 / 1_000_000.0) * output_rate;
81	
82	            let turn_baseline_cost = (usage.prompt_tokens() as f64 / 1_000_000.0) * input_rate
83	                + (usage.output_tokens as f64 / 1_000_000.0) * output_rate;
84	
85	            input_tokens += usage.input_tokens;
86	            output_tokens += usage.output_tokens;
87	            cache_creation_tokens += usage.cache_creation_tokens;
88	            cache_read_tokens += usage.cache_read_tokens;
89	            total_cost_usd += turn_cost;
90	            baseline_cost_no_cache_usd += turn_baseline_cost;
91	        }
92	
93	        let prompt_total = input_tokens + cache_creation_tokens + cache_read_tokens;
94	        let cache_hit_ratio =
95	            if prompt_total > 0 { (cache_read_tokens as f32 / prompt_total as f32) * 100.0 } else { 0.0 };
96	
97	        let net_savings_usd = (baseline_cost_no_cache_usd - total_cost_usd).max(0.0);
98	
99	        let efficiency_multiplier =
100	            if total_cost_usd > 0.0 { (baseline_cost_no_cache_usd / total_cost_usd) as f32 } else { 1.0 };
101	
102	        let mut per_model = HashMap::new();
103	        if !turns.is_empty() {
104	            per_model.insert(
105	                CompactString::new(model_name),
106	                ModelTokenSummary {
107	                    input_tokens,
108	                    output_tokens,
109	                    cache_creation_tokens,
110	                    cache_read_tokens,
111	                    cost_usd: total_cost_usd,
112	                    turns: turns.len() as u64,
113	                },
114	            );
115	        }
116	
117	        Self {
118	            input_tokens,
119	            output_tokens,
120	            cache_creation_tokens,
121	            cache_read_tokens,
122	            ephemeral_5m_tokens: cache_creation_tokens,
123	            ephemeral_1h_tokens: 0,
124	            cache_hit_ratio,
125	            total_cost_usd,
126	            provided_cost_usd,
127	            baseline_cost_no_cache_usd,
128	            net_savings_usd,
129	            efficiency_multiplier,
130	            per_model,
131	            reasoning_output_tokens: 0,
132	        }
133	    }
