    while True:
        b = buf[pos]; result |= (b & 0x7f) << shift; pos += 1
        if not (b & 0x80): break
        shift += 7
    return result, pos

def parse_field20_pairs(buf):
    # find all field=20 (tag = 20<<3|2 = 162) length-delimited entries, and within each,
    # extract field1(key)/field2(value) strings
    pos = 0
    pairs = []
    while pos < len(buf):
        try:
            tag, pos2 = decode_varint(buf, pos)
        except IndexError:
            break
        field_num = tag >> 3
        wire_type = tag & 0x7
        if wire_type == 2:
            length, pos3 = decode_varint(buf, pos2)
            if pos3 + length > len(buf):
                pos = pos2
                continue
            sub = buf[pos3:pos3+length]
            if field_num == 20:
                # parse key/value inside
                try:
                    p = 0
                    key = val = None
                    while p < len(sub):
                        t, p = decode_varint(sub, p)
                        fn = t >> 3; wt = t & 0x7
                        if wt == 2:
                            l, p = decode_varint(sub, p)
                            s = sub[p:p+l]; p += l
                            try:
