49	impl TokenEconomics {
50	    /// Computes full economic summary from one [`TurnPricingInput`] per turn. Each turn is
51	    /// priced independently via `pricing.rate_for` at that turn's own timestamp/tier, and the
52	    /// per-turn costs are summed into `total_cost_usd` -- required so a session whose turns
53	    /// straddle a price-change boundary is priced correctly on both sides. Token counters
54	    /// remain simple sums across turns, unaffected by the per-turn pricing. An empty `turns`
55	    /// slice returns a zeroed `TokenEconomics`, not an error.
56	    pub fn calculate(
57	        turns: &[TurnPricingInput],
58	        model_name: &str,
59	        pricing: &PricingTable,
60	        provided_cost_usd: Option<f64>,
61	    ) -> Self {
62	        let mut input_tokens = 0u64;
63	        let mut output_tokens = 0u64;
64	        let mut cache_creation_tokens = 0u64;
65	        let mut cache_read_tokens = 0u64;
66	        let mut reasoning_tokens_total = 0u64;
67	        let mut total_cost_usd = 0.0f64;
68	        let mut baseline_cost_no_cache_usd = 0.0f64;
69	
70	        for turn in turns {
71	            let usage = &turn.usage;
72	            let tier = turn.tier.as_deref();
73	
74	            let input_rate = pricing.rate_for(model_name, tier, TokenRateKind::Input, turn.timestamp);
75	            let cache_write_rate = pricing.rate_for(model_name, tier, TokenRateKind::CacheWrite, turn.timestamp);
76	            let cache_read_rate = pricing.rate_for(model_name, tier, TokenRateKind::CacheRead, turn.timestamp);
77	            let output_rate = pricing.rate_for(model_name, tier, TokenRateKind::Output, turn.timestamp);
78	            let reasoning_rate = pricing.rate_for(model_name, tier, TokenRateKind::Reasoning, turn.timestamp);
79	
80	            let turn_cost = (usage.input_tokens as f64 / 1_000_000.0) * input_rate
81	                + (usage.cache_creation_tokens as f64 / 1_000_000.0) * cache_write_rate
82	                + (usage.cache_read_tokens as f64 / 1_000_000.0) * cache_read_rate
83	                + (usage.output_tokens as f64 / 1_000_000.0) * output_rate
84	                + (usage.reasoning_tokens as f64 / 1_000_000.0) * reasoning_rate;
85	
86	            // Reasoning tokens are priced at the same rate in both the actual and no-cache
87	            // baseline cost -- caching doesn't apply to reasoning tokens, so omitting this term
88	            // from one side but not the other would skew net_savings_usd/efficiency_multiplier.
89	            let turn_baseline_cost = (usage.prompt_tokens() as f64 / 1_000_000.0) * input_rate
90	                + (usage.output_tokens as f64 / 1_000_000.0) * output_rate
91	                + (usage.reasoning_tokens as f64 / 1_000_000.0) * reasoning_rate;
92	
93	            input_tokens += usage.input_tokens;
94	            output_tokens += usage.output_tokens;
95	            cache_creation_tokens += usage.cache_creation_tokens;
96	            cache_read_tokens += usage.cache_read_tokens;
97	            reasoning_tokens_total += usage.reasoning_tokens;
98	            total_cost_usd += turn_cost;
99	            baseline_cost_no_cache_usd += turn_baseline_cost;
100	        }
101	
102	        let prompt_total = input_tokens + cache_creation_tokens + cache_read_tokens;
103	        let cache_hit_ratio =
104	            if prompt_total > 0 { (cache_read_tokens as f32 / prompt_total as f32) * 100.0 } else { 0.0 };
105	
106	        let net_savings_usd = (baseline_cost_no_cache_usd - total_cost_usd).max(0.0);
107	
108	        let efficiency_multiplier =
109	            if total_cost_usd > 0.0 { (baseline_cost_no_cache_usd / total_cost_usd) as f32 } else { 1.0 };
110	
111	        let mut per_model = HashMap::new();
112	        if !turns.is_empty() {
113	            per_model.insert(
114	                CompactString::new(model_name),
115	                ModelTokenSummary {
116	                    input_tokens,
117	                    output_tokens,
118	                    cache_creation_tokens,
119	                    cache_read_tokens,
120	                    reasoning_tokens: reasoning_tokens_total,
121	                    cost_usd: total_cost_usd,
122	                    turns: turns.len() as u64,
123	                },
124	            );
125	        }
126	
127	        Self {
128	            input_tokens,
129	            output_tokens,
130	            cache_creation_tokens,
131	            cache_read_tokens,
132	            ephemeral_5m_tokens: cache_creation_tokens,
133	            ephemeral_1h_tokens: 0,
134	            cache_hit_ratio,
135	            total_cost_usd,
136	            provided_cost_usd,
137	            baseline_cost_no_cache_usd,
138	            net_savings_usd,
139	            efficiency_multiplier,
140	            per_model,
141	            reasoning_output_tokens: reasoning_tokens_total,
142	        }
143	    }
144	}
