fn test_claude_1h_cache_write_rate_is_distinct_from_5m() {
    let table = PricingTable::seed();
    let as_of = Utc.with_ymd_and_hms(2026, 8, 21, 0, 0, 0).unwrap();

    let cases: &[(&str, f64, f64)] = &[
        // (model, 5m CacheWrite, 1h CacheWrite1h)
